Automatic deref conversion of &T into &U when trying to force-fit into a type
&x -> &(*x) -> &x.deref()

let string = String::from("hello");
let string1 = &string; // &String type
let string2: &str = &string; // &str type (Deref coercion)

let a = 5;
let b = a;
println!("a = {}", a);  // Works
println!("b = {}", b);  // Works

let a = String::from("Hello");
let b = a;

// println!("{}", a); Error: a no longer owns the value
println!("{}", b); // Ok: b now owns the value

let a = String::from("Hello");
let b = &a;
println!("a = {}", a);
println!("b = {}", b);

let x = 5;
let r = &a;
println!("x = {}, r = {}", x, r);

let mut a = 3;
let b = &a;

let mut name = String::from("John");
let name_ref = &mut name;
name_ref.push_str(" Doe");

println!("{}", name_ref); // John Doe, only use name or name_ref here

