let mut count = 1;
loop {
  println!("Hello World!");
  if count == 3 {
    break;
  }
  count += 1;
}

let mut count = 1;
let result = loop {
  println!("Hello!");
  if count == 3 {
    break count; // Stop the loop and return the number 3
  }
  count += 1;
};
println!("The loop stopped at: {}", result);

let mut count = 1;
while count <= 5 {
  println!("Count: {}", count);
  count += 1;
}

let mut num = 1;
while num <= 10 {
  if num == 6 {
    break; // Premature break
  }
  println!("Number: {}", num);
  num += 1;
}

let mut num = 1;

while num <= 10 {
  if num == 6 {
    num += 1;
    continue; // Skipped value
  }
  println!("Number: {}", num);
  num += 1;
}

for i in 1..6 {
  println!("i is: {}", i);
}

for i in 1..=10 {
  if i == 3 {
    continue; // skip 3
  }
  if i == 5 {
    break; // stop before printing 5
  }
  println!("i is: {}", i);
}

for x in &some_collection {
    println!("{}", x);
}
->
let mut iter = &some_collection.into_iter();
while let Some(x) = iter.next() {
    println!("{}", x);
}

